create temp table name_updates on commit drop as select r.* from import_plan p,jsonb_to_recordset(p.data->'renames')r(id integer,old text,name text,champ integer,team text);
do $$ begin
 if exists(select 1 from name_updates r left join public.players p on p.id=r.id where p.id is null or p.name<>r.old or p.championship_id<>r.champ or p.team<>r.team) then raise exception 'Names changed since roster review';end if;
 if exists(select 1 from import_plan p,jsonb_to_recordset(p.data->'teams')r(id integer,name text,champ integer) left join public.teams t on t.id=r.id where t.id is null or t.name<>r.name or t.championship_id<>r.champ)then raise exception 'Teams changed since roster review';end if;
end $$;
select set_config('ksliga.skip_player_stat_sync','on',true);
update public.players p set name=r.name from name_updates r where p.id=r.id;
insert into private.player_name_aliases(championship_id,team,alias_key,player_id)select champ,team,private.player_name_key(old),id from name_updates on conflict(championship_id,team,alias_key)do update set player_id=excluded.player_id;
update public.match_goals e set player_name=r.name from name_updates r,public.matches m where e.match_id=m.id and m.championship_id=r.champ and private.player_name_key(e.team_name)=private.player_name_key(r.team) and private.player_name_key(e.player_name)=private.player_name_key(r.old);
update public.match_cards e set player_name=r.name from name_updates r,public.matches m where e.match_id=m.id and m.championship_id=r.champ and private.player_name_key(e.team_name)=private.player_name_key(r.team) and private.player_name_key(e.player_name)=private.player_name_key(r.old);
update public.voting_candidates e set player_name=r.name from name_updates r,public.matches m where e.match_id=m.id and m.championship_id=r.champ and private.player_name_key(e.team_name)=private.player_name_key(r.team) and private.player_name_key(e.player_name)=private.player_name_key(r.old);
select set_config('ksliga.skip_player_stat_sync','',true);
-- The existing atomic roster triggers insert missing profiles with zero statistics.
update public.teams t set roster=array(select jsonb_array_elements_text(r.roster))from import_plan p,jsonb_to_recordset(p.data->'teams')r(id integer,roster jsonb)where t.id=r.id;
do $$ begin
 if exists(select 1 from name_updates r join public.players p on p.id=r.id join private.player_dedup_backup b on b.migration='20261111190950' cross join lateral jsonb_array_elements(b.payload->'players')previous(value) where(previous.value->>'id')::integer=p.id and (p.goals<>(previous.value->>'goals')::integer or p.yellow_cards<>(previous.value->>'yellow_cards')::integer or p.red_cards<>(previous.value->>'red_cards')::integer))then raise exception 'Existing statistics changed during import';end if;
end $$;
commit;
